import{_ as i,c as e,o as s,ag as l}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"螢幕錄製權限指南（macOS）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/screen-recording.md","filePath":"zh-TW/guide/screen-recording.md","lastUpdated":1794112334000}'),t={name:"zh-TW/guide/screen-recording.md"};function r(o,a,n,c,p,h){return s(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="螢幕錄製權限指南-macos" tabindex="-1">螢幕錄製權限指南（macOS） <a class="header-anchor" href="#螢幕錄製權限指南-macos" aria-label="Permalink to &quot;螢幕錄製權限指南（macOS）&quot;">​</a></h1><h2 id="為什麼-nicasa-需要螢幕錄製權限" tabindex="-1">為什麼 Nicasa 需要螢幕錄製權限？ <a class="header-anchor" href="#為什麼-nicasa-需要螢幕錄製權限" aria-label="Permalink to &quot;為什麼 Nicasa 需要螢幕錄製權限？&quot;">​</a></h2><p>在 macOS 上，截圖與螢幕擷取類應用程式必須取得螢幕錄製權限，才能讀取顯示器上的像素。</p><p>從 macOS 10.15 Catalina 開始，Apple 導入了更嚴格的隱私權保護。任何擷取螢幕內容（包括截圖）的應用程式都必須取得使用者的明確授權。</p><p>這適用於所有應用程式，包括從 Mac App Store 下載的應用程式。</p><p><strong>沒有該權限，Nicasa 無法截圖或錄製螢幕內容。</strong></p><h2 id="如何開啟螢幕錄製權限" tabindex="-1">如何開啟螢幕錄製權限 <a class="header-anchor" href="#如何開啟螢幕錄製權限" aria-label="Permalink to &quot;如何開啟螢幕錄製權限&quot;">​</a></h2><p>請依下列步驟操作：</p><ol><li>開啟 <strong>系統設定</strong></li><li>進入 <strong>隱私權與安全性</strong></li><li>選擇 <strong>螢幕錄製</strong></li><li>在清單中找到 <strong>Nicasa</strong> 並勾選</li></ol><p>如果應用程式當時已在執行，請在授予權限後重新啟動 Nicasa。</p><h2 id="如果權限提示沒有出現" tabindex="-1">如果權限提示沒有出現 <a class="header-anchor" href="#如果權限提示沒有出現" aria-label="Permalink to &quot;如果權限提示沒有出現&quot;">​</a></h2><p>權限對話框通常會在應用程式首次嘗試擷取螢幕時出現。</p><p>如果你沒有看到該提示，可能是因為：</p><ul><li>權限請求先前被拒絕過</li><li>macOS 快取了權限狀態</li><li>應用程式在對話框出現之前就執行了擷取</li></ul><p>這種情況下，你可能需要重設該權限。</p><h2 id="重設螢幕錄製權限" tabindex="-1">重設螢幕錄製權限 <a class="header-anchor" href="#重設螢幕錄製權限" aria-label="Permalink to &quot;重設螢幕錄製權限&quot;">​</a></h2><p>你可以在終端機中使用以下指令重設權限：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>執行指令後：</p><ol><li>重新啟動 Nicasa</li><li>再次觸發截圖功能</li><li>macOS 應會重新顯示權限對話框</li></ol><h2 id="如果重設仍然無效" tabindex="-1">如果重設仍然無效 <a class="header-anchor" href="#如果重設仍然無效" aria-label="Permalink to &quot;如果重設仍然無效&quot;">​</a></h2><p>極少數情況下，macOS 可能會保留無效的權限狀態。</p><p>如果重設權限沒有解決問題，請嘗試以下步驟：</p><ol><li>結束 Nicasa</li><li>從「應用程式」檔案夾中刪除 Nicasa</li><li>從 Mac App Store 重新安裝最新版本</li><li>再次啟動應用程式</li><li>當 macOS 要求螢幕錄製權限時，選擇 <strong>允許</strong></li></ol><p>重新安裝應用程式可以促使 macOS 重建權限記錄。</p><h2 id="另一種手動修復方法" tabindex="-1">另一種手動修復方法 <a class="header-anchor" href="#另一種手動修復方法" aria-label="Permalink to &quot;另一種手動修復方法&quot;">​</a></h2><p>你也可以手動切換一次權限：</p><ol><li>開啟 <strong>系統設定</strong></li><li>進入 <strong>隱私權與安全性</strong></li><li>開啟 <strong>螢幕錄製</strong></li><li>取消勾選 Nicasa，然後重新勾選</li><li>重新啟動 Nicasa</li></ol><h2 id="安全性說明" tabindex="-1">安全性說明 <a class="header-anchor" href="#安全性說明" aria-label="Permalink to &quot;安全性說明&quot;">​</a></h2><p>授予螢幕錄製權限並不會讓 Nicasa 控制你的系統。</p><p>它僅允許應用程式為截圖與擷取功能讀取螢幕像素。</p><p>你可以隨時在以下位置撤銷該權限： <strong>系統設定 → 隱私權與安全性 → 螢幕錄製</strong></p>',32)])])}const u=i(t,[["render",r]]);export{g as __pageData,u as default};
